using System;using System.ComponentModel;using System.Collections.Generic;using System.Globalization;using System.Drawing;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class GroundingForm:Form {
Project project;Board board;Circuit circuit;GroundingSource source;CircuitConductors wiring;CheckBox split=new CheckBox{Text="Separação PEN neste quadro (TN-C-S)",AutoSize=true};TextBox result=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Bottom,Height=145};readonly List<Action> readers=new List<Action>();public bool Changed{get;private set;}
public GroundingForm(Project p,Board b,Circuit c){project=p;board=b;circuit=c;source=p.GroundingSource==null?new GroundingSource():p.GroundingSource.Copy();wiring=c==null?null:c.Conductors==null?new CircuitConductors():c.Conductors.Copy();Text="Aterramento e condutores — "+b.Name+(c==null?"":" / "+c.Id);Size=new Size(1100,760);MinimumSize=new Size(900,650);Font=new Font("Segoe UI",10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.Controls.Add(new Label{Text="Fonte / um grupo comum de massas e terra por projeto",Dock=DockStyle.Fill},0,0);layout.Controls.Add(new Label{Text=c==null?"Selecione um circuito para definir seus condutores":"Condutores de "+c.Id+" / "+c.Name,Dock=DockStyle.Fill},1,0);layout.Controls.Add(TypedFields.Create(source,readers),0,1);layout.Controls.Add(TypedFields.Create(wiring,readers),1,1);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};split.Checked=b.SeparatesPEN;bar.Controls.Add(split);var apply=new Button{Text="Aplicar e recalcular",AutoSize=true};bar.Controls.Add(apply);apply.Click+=(s,e)=>{try{ApplyDraft();}catch(Exception ex){result.Text="Nenhuma alteração. "+ex.Message;}};Controls.Add(layout);Controls.Add(result);Controls.Add(bar);result.Text="Edite as cópias e aplique. Vazio significa desconhecido; zero em resistência é ideal declarado. Não inferir N/PE/PEN de número de polos. Fonte/esquema e condutores são validados juntos; mudança incompatível é revertida. Referência/versão/condições precisam identificar os dados. Para migrar esquema, remova/ajuste primeiro ligações incompatíveis; nunca desconectar o PE da instalação real por este painel.";}
public void ApplyDraft(){foreach(var read in readers)read();var old=project.GroundingSource;string oldName=project.Earthing;var oldW=circuit==null?null:circuit.Conductors;bool oldSplit=board.SeparatesPEN;project.GroundingSource=source.Copy();project.Earthing=Grounding.Name(source.Scheme);if(circuit!=null)circuit.Conductors=wiring.Copy();board.SeparatesPEN=split.Checked;try{project.Validate();var study=Engineering.Analyze(project);result.Text=circuit==null?"Fonte registrada. Defina os condutores dos circuitos; nenhum estudo de falta/tempo é aprovado por este cadastro.":Grounding.Describe(project,circuit);Changed=true;}catch{project.GroundingSource=old;project.Earthing=oldName;if(circuit!=null)circuit.Conductors=oldW;board.SeparatesPEN=oldSplit;throw;}}
}
internal static class TypedFields {
public static string Friendly(object item){string text=Convert.ToString(item);switch(text){case "LineNeutral":return "Fase-neutro";case "LineEarth":return "Fase-massa/terra";case "ITFirst":return "IT: primeira falta";case "ITSecond":return "IT: segunda falta";case "TransientContactAndTime":return "Contato transitório e tempo";case "ContactLimitAndTime":return "Limite de contato e tempo";case "TimeOnlyWithJustification":return "Somente tempo, justificado";case "ITFirstContinuity":return "IT1: continuidade monitorada";case "Final":return "Circuito final";case "Distribution":return "Distribuição/alimentador";case "PrimaryBreaker":return "Disjuntor primário";case "SelectedFuse":return "Fusível selecionado";case "SelectedResidual":return "Diferencial selecionado";case "None":return "Sem dispositivo de corte";case "DeclaredRange":return "Tempo total em faixa";case "AttachedTimeEnvelope":return "Envelope t-I anexado";case "RemoteEarth":return "Terra remota";case "SourceNeutral":return "Neutro da fonte";case "Explicit":return "Impedâncias N/PEN explícitas";case "Ideal":return "Neutro ideal, hipótese explícita";case "NoNeutralLoads":return "Sem cargas que utilizem neutro";case "FlowSinusoidal":return "Fluxo fundamental + prova senoidal";case "ExternalRms":return "RMS externo por condutor";case "BusbarAssembly":return "Conjunto de barramentos";case "BuswayAssembly":return "Conjunto busway";case "InstantaneousSigned":return "Amostras instantâneas assinadas";case "SymmetricRmsEnvelope":return "Envelope AC simétrico RMS";case "Linear":return "Linear";case "LogLog":return "Log-log (somente envelope positivo)";case "NetworkEquivalent":return "Equivalente da rede";case "RotatingInitial":return "Máquina girante, instante inicial";case "WyeNeutral":return "Estrela com neutro";case "Delta":return "Delta trifásico";case "SingleLN":return "Monofásica fase-neutro";case "SingleLL":return "Monofásica fase-fase";case "ConstantPower":return "Potência P+jQ constante";case "ConstantImpedance":return "Impedância constante";case "FullPhase":return "Mesma seção da fase";case "Reduced":return "Reduzido, com prova";case "RelatedPhase":return "Relação com seção de fase";case "Adiabatic":return "Adiabático com dados";case "Neutral":return "Neutro";case "Unknown":return "A definir";case "TNS":return "TN-S";case "TNC":return "TN-C";case "TNCS":return "TN-C-S";case "Direct":return "Direta";case "Isolated":return "Isolado";case "Impedance":return "Por impedância";case "LineLine":return "Fase-fase";case "ThreePhase":return "Trifásica sem neutro utilizado";case "ThreePhaseNeutral":return "Trifásica com neutro";case "ClassI":return "Classe I";case "ClassII":return "Classe II";default:return text;}}
public static Control Create(object draft,List<Action> readers){var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,AutoScroll=true,Padding=new Padding(5)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,51));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,49));if(draft==null)return panel;int row=0;foreach(PropertyDescriptor property in TypeDescriptor.GetProperties(draft)){if(!property.IsBrowsable)continue;var descriptor=property;Type type=Nullable.GetUnderlyingType(property.PropertyType)??property.PropertyType;object value=property.GetValue(draft);var label=new Label{Text=property.DisplayName,AutoSize=false,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};Control input;if(type.IsEnum){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};combo.FormattingEnabled=true;combo.Format+=(sender,e)=>e.Value=Friendly(e.ListItem);foreach(var item in Enum.GetValues(type))combo.Items.Add(item);combo.SelectedItem=value;input=combo;readers.Add(()=>descriptor.SetValue(draft,combo.SelectedItem));}else if(type==typeof(bool)){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};bool nullable=Nullable.GetUnderlyingType(property.PropertyType)!=null;if(nullable){combo.Items.AddRange(new object[]{"Desconhecido","Sim","Não"});combo.SelectedIndex=value==null?0:(bool)value?1:2;readers.Add(()=>descriptor.SetValue(draft,combo.SelectedIndex==0?null:(object)(combo.SelectedIndex==1)));}else{combo.Items.AddRange(new object[]{"Sim","Não"});combo.SelectedIndex=(bool)value?0:1;readers.Add(()=>descriptor.SetValue(draft,combo.SelectedIndex==0));}input=combo;}else{var box=new TextBox{Text=value==null?"":Convert.ToString(value,CultureInfo.CurrentCulture),Dock=DockStyle.Fill};input=box;readers.Add(()=>{if(type==typeof(string)){descriptor.SetValue(draft,box.Text);return;}double number;if(String.IsNullOrWhiteSpace(box.Text)){if(Nullable.GetUnderlyingType(descriptor.PropertyType)==null)throw new System.IO.InvalidDataException("Informe valor explícito: "+descriptor.DisplayName);descriptor.SetValue(draft,null);return;}if((box.Text.Contains(".")&&box.Text.Contains(","))||!double.TryParse(box.Text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out number))throw new System.IO.InvalidDataException("Número inválido: "+descriptor.DisplayName);if(descriptor.PropertyType==typeof(int)){if(number!=Math.Truncate(number)||number<int.MinValue||number>int.MaxValue)throw new System.IO.InvalidDataException("Inteiro inválido: "+descriptor.DisplayName);descriptor.SetValue(draft,(int)number);}else descriptor.SetValue(draft,number);});}panel.RowStyles.Add(new RowStyle(SizeType.Absolute,34));panel.Controls.Add(label,0,row);panel.Controls.Add(input,1,row++);}panel.AutoScrollMinSize=new Size(0,row*34+10);panel.RowCount=row+1;panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));return panel;}
}
partial class Studio {void ConfigureGrounding(){if(board==null)throw new InvalidOperationException("Selecione um quadro.");using(var form=new GroundingForm(project,board,circuit)){form.ShowDialog(this);if(form.Changed)Change();}}}
